type Page struct {
	ID      string `json:"id"`
	URL     string `json:"url"`
	Title   string `json:"title"`
	Snippet string `json:"snippet"`
	Depth   string `json:"depth"`
	Status  string `json:"status"`
	HTML    string `json:"html,omitempty"`
}

func main() {
	seed := env("SILC_SCRAPE_URL", "")
	if seed == "" {
		fatal("SILC_SCRAPE_URL required")
	}
	depth, _ := strconv.Atoi(env("SILC_SCRAPE_DEPTH", "2"))
	if depth < 1 {
		depth = 1
	}
	if depth > 5 {
		depth = 5
	}
	sameHost := env("SILC_SCRAPE_SAME_HOST", "true") != "false"
	linkCSS := env("SILC_SCRAPE_LINK_CSS", "a[href]")
	includeHTML := env("SILC_SCRAPE_INCLUDE_HTML", "false") == "true"

	seedURL, err := url.Parse(seed)
	if err != nil {
		fatal(err.Error())
	}

	var mu sync.Mutex
	pages := make([]Page, 0, 64)
	seen := map[string]bool{}

	c := colly.NewCollector(
		colly.MaxDepth(depth),
		colly.Async(true),
	)
	_ = c.Limit(&colly.LimitRule{DomainGlob: "*", Parallelism: 8, Delay: 0})

	c.OnHTML("html", func(e *colly.HTMLElement) {
		reqURL := e.Request.URL.String()
		mu.Lock()
		if seen[reqURL] {
			mu.Unlock()
			return
		}
		seen[reqURL] = true
		mu.Unlock()

		title := strings.TrimSpace(e.ChildText("title"))
		if title == "" {
			title = strings.TrimSpace(e.ChildText("h1"))
		}
		body := strings.TrimSpace(e.ChildText("body"))
		snippet := body
		if len(snippet) > 280 {
			snippet = snippet[:280] + "…"
		}
		page := Page{
			ID:      fmt.Sprintf("%x", hash(reqURL)),
			URL:     reqURL,
			Title:   title,
			Snippet: snippet,
			Depth:   strconv.Itoa(e.Request.Depth),
			Status:  "ok",
		}
		if includeHTML {
			page.HTML, _ = e.DOM.Html()
		}
		mu.Lock()
		pages = append(pages, page)
		mu.Unlock()
	})

	c.OnHTML(linkCSS, func(e *colly.HTMLElement) {
		href := e.Attr("href")
		if href == "" || strings.HasPrefix(href, "#") || strings.HasPrefix(href, "mailto:") {
			return
		}
		abs := e.Request.AbsoluteURL(href)
		if abs == "" {
			return
		}
		u, err := url.Parse(abs)
		if err != nil {
			return
		}
		if sameHost && !strings.EqualFold(u.Host, seedURL.Host) {
			return
		}
		_ = e.Request.Visit(abs)
	})

	c.OnError(func(r *colly.Response, err error) {
		reqURL := r.Request.URL.String()
		mu.Lock()
		pages = append(pages, Page{
			ID:     fmt.Sprintf("%x", hash(reqURL)),
			URL:    reqURL,
			Depth:  strconv.Itoa(r.Request.Depth),
			Status: "error",
			Snippet: err.Error(),
		})
		mu.Unlock()
	})

	if err := c.Visit(seed); err != nil {
		fatal(err.Error())
	}
	c.Wait()

	enc := json.NewEncoder(os.Stdout)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(pages); err != nil {
		fatal(err.Error())
	}
}

